@Entity
@Inheritance(strategy = InheritanceType.JOINED)        // or SINGLE_TABLE / TABLE_PER_CLASS
@DiscriminatorColumn(name = "payment_type")
public abstract class Payment { @Id Long id; String name; }

@Entity @DiscriminatorValue("card")
public class CreditCardPayment extends Payment { String cardNumber; }
// em.find(Payment.class, 42L) materialises the concrete subclass from the row

